#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

int main(int argc, char *argv[])
{
    /* No argument */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr = NULL;
    errno = 0;
    long n = strtol(argv[1], &endptr, 10);

    /* Bad input: not a number or overflow */
    if (endptr == argv[1] || *endptr != '\0' || errno != 0) {
        puts("BAD_INPUT");
        return 0;
    }

    if (n < 1) {
        puts("BAD_INPUT");
        return 0;
    }

    if (n > 1000000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    long cur = n;
    long steps = 0;

    while (cur != 1) {
        if (steps > 999999) {
            puts("STEP_LIMIT_EXCEEDED");
            return 0;
        }
        if (cur > 1000000000000000L) {
            puts("OVERFLOW_GUARD");
            return 0;
        }
        if ((cur & 1) == 0) {
            cur = cur >> 1;
        } else {
            cur = cur * 3 + 1;
        }
        ++steps;
    }

    printf("n=%ld steps=%ld\n", n, steps);
    return 0;
}
